#include <stdio.h>
int main(void) {
    // 使用 long long，统一承载读入的整数及其和。
    long long a, b;
    if (scanf("%lld %lld", &a, &b) != 2) return 0;
    // 两个有符号整数直接相加，负数和零无需特殊判断。
    long long sum = a + b;
    // 输出整数并换行，不附加说明文字。
    printf("%lld\n", sum);
    return 0;
}

