#include <iostream>
int main() {
    // 用 long long 读取整数，预留足够的取值范围。
    long long a, b;
    if (!(std::cin >> a >> b)) return 0;
    // 加法对正数、负数和零都遵循同一条规则。
    long long sum = a + b;
    // 按题目协议只输出答案和一个换行。
    std::cout << sum << '\n';
    return 0;
}

STDIO.java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        // Scanner 按空白分隔读取输入，换行和空格都可作为分隔符。
        Scanner input = new Scanner(System.in);
        long a = input.nextLong();
        long b = input.nextLong();
        // long 可承载输入值及它们的和，避免类型范围造成误判。
        long sum = a + b;
        // 标准输出中只放答案，println 自动追加换行。
        System.out.println(sum);
    }
}

STDIO.rust:
use std::io::{self, Read};
fn main() {
    // 一次读取输入，并按空白获取两个整数。
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let a: i64 = values.next().unwrap().parse().unwrap();
    let b: i64 = values.next().unwrap().parse().unwrap();
    // i64 保留正负号和足够的取值范围。
    let sum = a + b;
    // 只输出结果，println! 自动追加换行。
    println!("{}", sum);
}
